from pathlib import Path
import json,re
root=Path(__file__).resolve().parents[1]
bib=(root/'literature/references.bib').read_text()
rows=[
('visualprompt','Visual Prompting via Image Inpainting','2022; NeurIPS 35; 25005–25017','https://papers.nips.cc/paper_files/paper/2022/hash/9f09f316a3eaf59d9ced5ffaefe97e0f-Abstract-Conference.html',['turn96view0','turn123search0'],'Abstract explicitly formulates prediction as completing a missing image region in an example-conditioned concatenated prompt. Title, author order, venue, year, pages and DOI match the official BibTeX endpoint.','SUPPORTED','No change.'),
('goodexamples','What Makes Good Examples for Visual In-Context Learning?','2023; NeurIPS 36; 17773–17794','https://proceedings.neurips.cc/paper_files/paper/2023/hash/398ae57ed4fda79d0781c65c926d667b-Abstract-Conference.html',['turn96view1','turn123search1'],'Abstract studies sensitivity to demonstration selection and introduces prompt retrieval. Current reference-variation motivation is supported; it does not imply the current project implemented that retrieval method. Official BibTeX verifies pages and DOI.','SUPPORTED','No factual change. Optional editorial replacement: “Prior work studies example selection” in place of the shortened paper name “Good Examples”.'),
('vrpsam','VRP-SAM: SAM with Visual Reference Prompt','2024; CVPR; 23565–23574','https://openaccess.thecvf.com/content/CVPR2024/html/Sun_VRP-SAM_SAM_with_Visual_Reference_Prompt_CVPR_2024_paper.html',['turn104search0','turn104search6'],'Official abstract introduces the Visual Reference Prompt encoder, trained with meta-learning. The report’s learned reference-prompt encoder description is accurate. Listed author prefix agrees with all nine authors in the proceedings.','SUPPORTED','No change.'),
('unicl','UNICL-SAM: Uncertainty-Driven In-Context Segmentation with Part Prototype Discovery','2025; CVPR; 20201–20211','https://openaccess.thecvf.com/content/CVPR2025/html/Sheng_UNICL-SAM_Uncertainty-Driven_In-Context_Segmentation_with_Part_Prototype_Discovery_CVPR_2025_paper.html',['turn104search1','turn104search2'],'Official abstract models unreliable examples caused by variable quality and inaccurate labeling, using uncertainty, feature refinement and part prototypes. Current phrase about uncertainty in imperfect examples is supported. Author prefix and page range match proceedings.','SUPPORTED','No change.'),
('sine','A Simple Image Segmentation Framework via In-Context Examples','2024; NeurIPS 37; 25095–25119','https://papers.nips.cc/paper_files/paper/2024/hash/2cc0b08447bf9668db268e6c86364a6e-Abstract-Conference.html',['turn98view0','turn123search2'],'Abstract explicitly names the In-context Interaction module for reference/target correlations, followed by a Matching Transformer. Current concise description is supported. Complete authors, pages, venue, year and DOI match official BibTeX.','SUPPORTED','No change.'),
('dinov3','DINOv3','2025; arXiv:2508.10104','https://arxiv.org/abs/2508.10104',['turn98view1','turn112view0','turn115view2'],'Abstract supports self-supervised scaling and dense representations; §6.1.3 tests geometric and semantic correspondence with frozen features. The co-citations beside INSID3 identify its backbone; INSID3 itself must support debiasing/clustering/aggregation, not DINOv3 alone. First six authors and arXiv identifier/year/DOI match.','SUPPORTED_WITH_CO_CITATION_SCOPE','No change.'),
('dinov2','DINOv2: Learning Robust Visual Features without Supervision','Current entry: 2023 arXiv; published version: TMLR January 2024','https://arxiv.org/abs/2304.07193',['turn98view2','turn108search9','turn112view1','turn115view1'],'Abstract establishes scale and generic features. §7.5 Patch matching demonstrates cross-image semantic correspondences. Existing 2023 arXiv entry is valid, but official TMLR paper is published January 2024 and gives author Huy V. Vo.','SUPPORTED_PUBLICATION_UPGRADE_RECOMMENDED','Prefer @article, journal={Transactions on Machine Learning Research}, year={2024}, url={https://openreview.net/forum?id=a68SUt6zFt}; use Vo, Huy V. Keep arXiv identifier as an optional access field.'),
('sam3','SAM 3: Segment Anything with Concepts','2025; arXiv:2511.16719 (v2 revised March 2026)','https://arxiv.org/abs/2511.16719',['turn98view3'],'Abstract defines concept prompts as noun phrases, exemplars or their combination and returns matching instance masks. This supports concept-level prompt capability. The CG-ICS co-citation must support its own concept-generation/search procedure. Listed author prefix and original arXiv year match.','SUPPORTED_WITH_CO_CITATION_SCOPE','No change. Do not interpret the 2026 revision date as the initial publication year.'),
('sam','Segment Anything','2023; ICCV; 4015–4026','https://openaccess.thecvf.com/content/ICCV2023/html/Kirillov_Segment_Anything_ICCV_2023_paper.html',['turn108search0','turn112view2','turn118view0'],'Official metadata verifies author prefix, pages, venue and year. Paper §3 specifies point/box/mask prompts and a mask decoder, supporting the spatial-prompt statement. The report does not claim SAM is exclusively spatial: paper also explores text prompts.','SUPPORTED','No change.'),
('qwen3vl','Qwen3-VL Technical Report','2025; arXiv:2511.21631','https://arxiv.org/abs/2511.21631',['turn101view1','turn125view0'],'Abstract supports multimodal reasoning and includes dense 4B variants. Official Qwen model card confirms Qwen3-VL-4B-Instruct. Local configs/source_pins.json and cluster.orion.recovery.json identify this checkpoint, independently of the paper citation. Original first six authors/year/title/identifier/DOI match.','SUPPORTED_WITH_IMPLEMENTATION_EVIDENCE','Keep citation attached to model identity. Working resolution, candidate count, loops and GPU allocation are implementation facts, not claims established by the Qwen paper.'),
('dino','Emerging Properties in Self-Supervised Vision Transformers','2021; ICCV; 9650–9660','https://openaccess.thecvf.com/content/ICCV2021/html/Caron_Emerging_Properties_in_Self-Supervised_Vision_Transformers_ICCV_2021_paper.html',['turn104search3','turn104search4'],'Abstract and Figure 1 describe object/segmentation structure emerging in self-supervised ViT features, without labels. All seven authors and publication fields match official proceedings. The report claims capability, not guaranteed correspondence on every image.','SUPPORTED','No change.'),
('vit','An Image Is Worth 16x16 Words: Transformers for Image Recognition at Scale','2021; ICLR','https://openreview.net/forum?id=YicbFdNTTy',['turn104search5'],'Official ICLR PDF explicitly applies Transformers to sequences of image patches, supporting patch-token description. First six authors, title and conference year match. Direct forum open was challenge-blocked; official PDF search supplied the accepted paper.','SUPPORTED','No change.'),
('sam2','SAM 2: Segment Anything in Images and Videos','Current entry: 2024 arXiv; published version: ICLR 2025','https://proceedings.iclr.cc/paper_files/paper/2025/hash/45c1f6a8cbf2da59ebf2c802b4f742cd-Abstract-Conference.html',['turn101view4','turn108search1','turn112view4'],'Official ICLR proceedings confirms title, authors, 2025 conference publication and promptable segmentation across images/videos. Current 2024 arXiv reference is valid but the published conference entry is preferable.','SUPPORTED_PUBLICATION_UPGRADE_RECOMMENDED','Prefer @inproceedings, booktitle={International Conference on Learning Representations}, year={2025}, official proceedings URL. Keep arXiv identifier as an optional access field.'),
('clip','Learning Transferable Visual Models From Natural Language Supervision','2021; ICML; PMLR 139:8748–8763','https://proceedings.mlr.press/v139/radford21a.html',['turn101view5'],'Official abstract and BibTeX verify image–text matching pretraining, author prefix, title, proceedings, year, volume and pages. This directly supports image–text alignment, without claiming a segmentation architecture.','SUPPORTED','No change.')
]
entries=[]
for key,title,meta,url,refs,evidence,status,action in rows:
 contexts=[]
 for p in sorted((root/'paper').rglob('*.tex')):
  if p.name.startswith('old_'):continue
  for n,line in enumerate(p.read_text().splitlines(),1):
   for m in re.finditer(r'\\cite\w*\{([^}]+)\}',line):
    if key in m[1].split(','):
     contexts.append({'file':str(p.relative_to(root)),'line':n,'paragraph':line,'citation_group':m[1]})
 entries.append({'key':key,'title':title,'verified_metadata':meta,'source_url':url,'web_refs':refs,'evidence_and_usage':evidence,'status':status,'recommended_action':action,'uses':contexts})
result={'date_sgt':'2026-11-17','scope':'14 assigned bibliography entries and every active citation occurrence; old_*.tex excluded','entry_count':len(entries),'citation_occurrences':sum(len(x['uses']) for x in entries),'methods':'Reopened primary paper/proceedings pages; search of official CVF/OpenReview source content used where direct retrieval blocked. NeurIPS official BibTeX retrieved independently through urllib after search tool rejected x-bibtex MIME. No reliance on old audit labels.','blocking_limitations':[],'retrieval_limitations':['Several direct CVF HTML requests returned 403; indexed official CVF content and PDF were successfully read.','OpenReview forum/PDF direct requests returned a verification page for ViT and DINOv2; official indexed PDF supplied publication metadata, with DINOv2 arXiv full text supplying method evidence.'],'entries':entries}
(root/'audit/bib_foundations.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
lines=['# Foundation and Visual In-Context Learning Reference Audit','', 'Audit date: 2026-11-17 (SGT). Checked 14 references and 18 active citation occurrences. Old, unused TeX sections were excluded.','', 'All 14 works were verified through primary paper/proceedings sources. Existing citations support the surrounding clauses. Two entries should preferably cite the published version: DINOv2 (TMLR 2024) and SAM 2 (ICLR 2025). Their existing preprint entries are valid rather than fabricated.','', '## Retrieval record','', result['methods'],'', 'Some direct CVF/OpenReview requests were blocked; the official source text was available through search, and author arXiv full text was used for detailed method verification. This is recorded rather than presented as a successful direct fetch.','']
for e in entries:
 lines += [f"## `{e['key']}` — {e['title']}",'',f"- Metadata: {e['verified_metadata']}.",f"- Primary source: [{e['title']}]({e['source_url']}).",f"- Finding: {e['evidence_and_usage']}",f"- Action: {e['recommended_action']}",'- Active uses:']
 for c in e['uses']:
  lines.append(f"  - `{c['file']}:{c['line']}`; citation group `{c['citation_group']}`.")
 lines += ['']
lines += ['## Proposed bibliography replacements','', 'Exact replacement entries are in `bib_foundations_replacements.bib`. No main bibliography or report source has been edited by this audit.','', '## Citation scope','', 'A foundation-model reference establishes the capabilities and identity of that model. It is not used as evidence that this project ran a particular configuration or achieved its measured results. INSID3/CG-ICS co-citations establish their processing pipelines; this project’s run bindings/configurations establish execution details.','']
(root/'audit/bib_foundations.md').write_text('\n'.join(lines))
# Reuse the existing verified author-prefix format, but select the published versions.
replacements=[]
for key in ['dinov2','sam2']:
 m=re.search(r'@\w+\{'+key+r',\n.*?\n\}',bib,re.S)
 s=m.group(0)
 if key=='dinov2':
  s=s.replace('@misc','@article',1).replace('Vo, Huy and','Vo, Huy V. and').replace('year = {2023}','year = {2024}').replace('  year =','  journal = {Transactions on Machine Learning Research},\n  year =').replace('https://arxiv.org/abs/2304.07193','https://openreview.net/forum?id=a68SUt6zFt')
 else:
  s=s.replace('@misc','@inproceedings',1).replace('year = {2024}','year = {2025}').replace('  year =','  booktitle = {International Conference on Learning Representations},\n  year =').replace('https://arxiv.org/abs/2408.00714','https://proceedings.iclr.cc/paper_files/paper/2025/hash/45c1f6a8cbf2da59ebf2c802b4f742cd-Abstract-Conference.html')
 # An arXiv DOI should not masquerade as the publication DOI.
 s=re.sub(r'^  doi = \{10\.48550/arXiv\.[^}]+\},\n','',s,flags=re.M)
 replacements.append(s)
(root/'audit/bib_foundations_replacements.bib').write_text('% Prefer published versions; arXiv identifiers retained as access metadata.\n\n'+'\n\n'.join(replacements)+'\n')
print('Created audit MD, JSON and 2 published-version replacement entries. Citations:',result['citation_occurrences'])
